// Walk It — Electron main process.
// Wraps the built web app (dist/) in a branded desktop window.
const { app, BrowserWindow, Menu, shell, nativeImage } = require("electron");
const path = require("path");

const isDev = !!process.env.WALKIT_DEV;
const shotPath = process.env.WALKIT_SHOT; // smoke-test: capture a screenshot then quit

function iconPath() {
  // packaged icons are generated by electron-builder; for dev/runtime use the PNG
  return path.join(__dirname, "..", "build", "icon.png");
}

function buildMenu() {
  const isMac = process.platform === "darwin";
  const template = [
    ...(isMac
      ? [{
          label: "Walk It",
          submenu: [
            { role: "about" },
            { type: "separator" },
            { role: "hide" },
            { role: "hideOthers" },
            { role: "unhide" },
            { type: "separator" },
            { role: "quit" },
          ],
        }]
      : []),
    {
      // required on macOS for Cmd+C / Cmd+V / Cmd+X / Cmd+A to work in inputs
      label: "Edit",
      submenu: [
        { role: "undo" },
        { role: "redo" },
        { type: "separator" },
        { role: "cut" },
        { role: "copy" },
        { role: "paste" },
        ...(isMac
          ? [{ role: "pasteAndMatchStyle" }, { role: "delete" }, { role: "selectAll" }]
          : [{ role: "delete" }, { type: "separator" }, { role: "selectAll" }]),
      ],
    },
    {
      label: "View",
      submenu: [
        { role: "reload" },
        { role: "forceReload" },
        { role: "toggleDevTools" },
        { type: "separator" },
        { role: "resetZoom" },
        { role: "zoomIn" },
        { role: "zoomOut" },
        { type: "separator" },
        { role: "togglefullscreen" },
        ...(!isMac ? [{ type: "separator" }, { role: "quit" }] : []),
      ],
    },
    {
      label: "Help",
      submenu: [
        {
          label: "Walk It on GitHub",
          click: () => shell.openExternal("https://github.com/slopenintercept/WalkIt"),
        },
      ],
    },
  ];
  Menu.setApplicationMenu(Menu.buildFromTemplate(template));
}

function createWindow() {
  const win = new BrowserWindow({
    width: 1440,
    height: 900,
    minWidth: 1024,
    minHeight: 640,
    backgroundColor: "#0b0e1a", // matches the app so there's no white flash
    title: "Walk It",
    icon: nativeImage.createFromPath(iconPath()),
    show: false,
    webPreferences: {
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  win.once("ready-to-show", () => win.show());

  // open external links (e.g. CDN docs) in the system browser, not a new window
  win.webContents.setWindowOpenHandler(({ url }) => {
    shell.openExternal(url);
    return { action: "deny" };
  });

  if (isDev) {
    win.loadURL("http://localhost:5173");
  } else {
    win.loadFile(path.join(__dirname, "..", "dist", "index.html"));
  }

  // smoke test: once loaded, save a screenshot of the real window and quit
  if (shotPath) {
    win.webContents.on("did-finish-load", () => {
      setTimeout(async () => {
        try {
          const img = await win.webContents.capturePage();
          require("fs").writeFileSync(shotPath, img.toPNG());
        } finally {
          app.quit();
        }
      }, 9000);
    });
  }
}

app.whenReady().then(() => {
  if (process.platform === "darwin") {
    app.dock?.setIcon(nativeImage.createFromPath(iconPath()));
  }
  buildMenu();
  createWindow();

  app.on("activate", () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") app.quit();
});
